IF Mode THEN
    autoMotorForward := FALSE;
    autoMotorReverse := FALSE;
    autoKick := FALSE;
    autoCompletionLight := FALSE;
    autoFiringTemp := 0.0; // or keep last? maybe output 0 if not qualified. We'll set default 0.

    CASE AutoState OF
        0: (* IDLE *)
            IF risingSensorFeed THEN
                AutoState := 1;
                autoMotorForward := TRUE;
            END_IF;

        1: (* FEED_TO_WASH *)
            autoMotorForward := TRUE;
            IF risingSensorWash THEN
                AutoState := 2;
                autoMotorForward := FALSE;
            END_IF;

        2: (* AT_WASH_WAIT *)
            autoMotorForward := FALSE;
            IF risingWashComplete THEN
                AutoState := 3;
                autoMotorForward := TRUE;
            END_IF;

        3: (* WASH_TO_WEIGHT *)
            autoMotorForward := TRUE;
            IF risingSensorWeight THEN
                AutoState := 4;
                autoMotorForward := FALSE;
            END_IF;

        4: (* AT_WEIGHT_WAIT *)
            autoMotorForward := FALSE;
            IF risingWeightComplete THEN
                IF (weight >= 100.0) AND (weight <= 200.0) THEN
                    autoFiringTemp := 500.0 + (weight - 100.0) * 0.5;
                    AutoState := 5;
                    autoMotorForward := TRUE;
                ELSE
                    autoKick := TRUE;
                    AutoState := 0; (* reject, return to idle *)
                    (* maybe motor stop already *)
                END_IF;
            END_IF;

        5: (* WEIGHT_TO_FIRING *)
            autoMotorForward := TRUE;
            IF risingSensorFiring THEN
                AutoState := 6;
                autoMotorForward := FALSE;
            END_IF;

        6: (* AT_FIRING_WAIT *)
            autoMotorForward := FALSE;
            IF risingFiringComplete THEN
                AutoState := 7;
                autoMotorForward := TRUE;
            END_IF;

        7: (* FIRING_TO_OUTPUT *)
            autoMotorForward := TRUE;
            IF risingSensorOutput THEN
                AutoState := 8;
                autoMotorForward := FALSE;
                autoCompletionLight := TRUE;
            END_IF;

        8: (* AT_OUTPUT *)
            autoMotorForward := FALSE;
            autoCompletionLight := TRUE;
            IF fallingSensorOutput OR NOT SensorOutput THEN
                AutoState := 0;
                autoCompletionLight := FALSE;
            END_IF;
    END_CASE;

    MotorForward := autoMotorForward;
    MotorReverse := autoMotorReverse; // auto always false
    kick := autoKick;
    CompletionLight := autoCompletionLight;
    firingTemp := autoFiringTemp;

